// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        // Make the call to withdraw fail by having alice be a contract that rejects ether
        // For simplicity, we simulate a failed call by not sending any ether and using a non-payable address
        // but the test must show divergence. We'll instead use an EOA that accepts ether.
        // Actually, the only way to force failure is to use a contract that reverts on receive.
        // But since the contract uses .call{}, it will not revert on failure but returns false.
        // The reference version reverts on false, the modified does not.
        // We can use a contract that rejects ether. Let's deploy a rejector.

        // Actually, we can use the test contract itself as the recipient by making withdraw from an address that is a contract without receive/fallback.
        // But the test contract inherits Test which has a receive? We'll create a simple contract that rejects.
        // Simpler: we directly test the boolean by calling withdraw from a contract that we control.
        // We'll set up a scenario where the call fails and check post-conditions.

        // Let's create a simple contract that reverts on receive.
        Rejector rejector = new Rejector();
        vm.deal(address(rejector), 0);
        // Fund the contract from rejector
        vm.deal(address(rejector), 1 ether);
        vm.prank(address(rejector));
        c.addToBalance{value: 1 ether}();

        // Now withdraw from rejector - this will cause the call to fail because Rejector's receive reverts
        vm.prank(address(rejector));
        // The reference version will revert the whole transaction, the modified version will not revert.
        // We need to catch the revert for the reference version and allow the call for the modified.
        // But the test must have the same call sequence. Since the reference reverts on failure, we must catch it.
        // Let's do: try withdraw, if it reverts, ok=false.
        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }
        // For the reference version, it will revert => ok == false. For the modified version, it will not revert => ok == true.
        // But then the assertion? We need the assert to pass on reference and fail on modified.
        // So assertTrue(!ok) would pass on reference (revert = false) and fail on modified. But modified returns ok=true, so !ok => false.
        // That is the divergence.
        assertTrue(!ok);
    }
}

contract Rejector {
    receive() external payable {
        revert("I reject ether");
    }
}

